/// Render an invoice like [`format_invoice`], but for drafts show the number
/// the invoice will receive when issued.
pub fn format_invoice_preview(invoice: &Invoice) -> String {
    if invoice.number != 0 {
        return format_invoice(invoice);
    }
    // Read-only peek at the sequence: previewing must never consume a number.
    let upcoming = NEXT_INVOICE.load(Ordering::SeqCst);
